// After a scripted goal: new summons on both sides, then para_cp0009 and
// para_cp0010 (team 0) lose theirs
CMND_BTL_SET_AVATER("para_cp0290", "ck0004", 1);
CMND_BTL_SET_AVATER("para_cp0008", "ck0030", 0);
CMND_BTL_RESET_AVATER(0, "para_cp0009");
CMND_BTL_RESET_AVATER(0, "para_cp0010");

// Three or more of team 0's Fighting Spirits are out: dismiss the one
// with the lowest gauge before a new summon
if (CMND_BTL_GET_AVATER_NUM(0) >= 3)
{
	CMND_BTL_RESET_AVATER(0);
}

CMND_BTL_SET_AVATER("para_cp0016", "ck0005", 0);
